def plaetze_fuellen(apps, schema_editor):
    """Vorhandene eigene und kurzfristige Touren: aus „Wer fährt“ werden Fahrer und Beifahrer,
    in der Reihenfolge der Namen (in der Maske der Tour zu berichtigen). Weitere Personen
    bleiben als Mitfahrende stehen."""
    Tour = apps.get_model("touren", "Tour")
    for tour in Tour.objects.filter(personen__isnull=False).distinct():
        felder = ["fahrer", "beifahrer", "beifahrer2"]
        leute = tour.personen.order_by("nachname", "vorname")[:3]
        for feld, person in zip(felder, leute, strict=False):
            setattr(tour, feld, person)
        tour.save(update_fields=felder)


